<?php require_once __DIR__.'/core.php'; hrRequireCsrf(); $companyId=hrCompanyId($hrDb); $uploadDir = __DIR__.'/uploads/company_logos'; if (!is_dir($uploadDir)) { mkdir($uploadDir, 0775, true); } if($_SERVER['REQUEST_METHOD']==='POST'){ $logoUrl=$companyId ? (string)hrCompany($hrDb)['logo_url'] : ''; $logoWidth=(int)($_POST['logo_width'] ?? 180); $logoHeight=(int)($_POST['logo_height'] ?? 52); $logoFit=trim((string)($_POST['logo_fit'] ?? 'contain')); if (!in_array($logoFit,['contain','cover','fill'],true)) { $logoFit='contain'; } if (!empty($_FILES['company_logo']['name'])) { $file = $_FILES['company_logo']; $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION)); if (in_array($ext,['png','jpg','jpeg','svg','webp'],true) && is_uploaded_file($file['tmp_name'])) { $safeName='company-'.$companyId.'-'.time().'.'.$ext; $target=$uploadDir.'/'.$safeName; if (move_uploaded_file($file['tmp_name'],$target)) { $logoUrl='uploads/company_logos/'.$safeName; } } } if(isset($_POST['new_company'])){$name=hrEsc($hrDb,$_POST['company_name']);$code=strtoupper(hrEsc($hrDb,$_POST['company_code']));$st=$hrDb->prepare('INSERT INTO hr_companies(company_name,company_code,email,phone,address,primary_color,payroll_day,logo_url,logo_width,logo_height,logo_fit) VALUES (?,?,?,?,?,?,?,?,?,?,?)');$pd=(int)$_POST['payroll_day'];$st->bind_param('ssssssissis',$name,$code,$_POST['email'],$_POST['phone'],$_POST['address'],$_POST['primary_color'],$pd,$logoUrl,$logoWidth,$logoHeight,$logoFit);if($st->execute()){$_SESSION['hr_company_id']=$st->insert_id;hrFlash('New company workspace created.');}else hrFlash('Company code must be unique.','error');$st->close();}else{$st=$hrDb->prepare('UPDATE hr_companies SET company_name=?,email=?,phone=?,address=?,primary_color=?,payroll_day=?,logo_url=?,logo_width=?,logo_height=?,logo_fit=? WHERE id=?');$pd=(int)$_POST['payroll_day'];$st->bind_param('sssssissisi',$_POST['company_name'],$_POST['email'],$_POST['phone'],$_POST['address'],$_POST['primary_color'],$pd,$logoUrl,$logoWidth,$logoHeight,$logoFit,$companyId);$st->execute();$st->close();hrFlash('Company setup saved.');}header('Location: company.php');exit;} $company=hrCompany($hrDb);hrPageStart('Company setup'); ?>
<div class="page-head"><div><h2>Company workspace</h2><p>Set the identity and payroll calendar for the active company.</p></div></div><div class="grid"><div class="form-card"><h3><?=htmlspecialchars($company['company_name'])?></h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=hrCsrf()?>"><div class="form-grid two"><label>Legal company name<input name="company_name" value="<?=htmlspecialchars($company['company_name'])?>" required></label><label>Company code<input value="<?=htmlspecialchars($company['company_code'])?>" disabled></label><label>Email<input type="email" name="email" value="<?=htmlspecialchars($company['email'])?>"></label><label>Phone<input name="phone" value="<?=htmlspecialchars($company['phone'])?>"></label><label>Brand color<input type="color" name="primary_color" value="<?=htmlspecialchars($company['primary_color'])?>"></label><label>Payroll working days<input type="number" min="1" max="31" name="payroll_day" value="<?=$company['payroll_day']?>"></label><label>Logo width<input type="number" min="32" max="300" name="logo_width" value="<?=max(32,(int)($company['logo_width'] ?? 180))?>"></label><label>Logo height<input type="number" min="24" max="160" name="logo_height" value="<?=max(24,(int)($company['logo_height'] ?? 52))?>"></label><label>Logo fit<select name="logo_fit"><option value="contain" <?=($company['logo_fit'] ?? 'contain')==='contain'?'selected':''?>>Contain</option><option value="cover" <?=($company['logo_fit'] ?? 'contain')==='cover'?'selected':''?>>Cover</option><option value="fill" <?=($company['logo_fit'] ?? 'contain')==='fill'?'selected':''?>>Fill</option></select></label><label>Company logo<input type="file" name="company_logo" accept=".png,.jpg,.jpeg,.svg,.webp"></label><?php if (!empty($company['logo_url'])): ?><div class="brand-preview"><img src="<?=htmlspecialchars($company['logo_url'])?>" alt="Company logo" style="max-width:180px;max-height:72px;object-fit:<?=htmlspecialchars((string)($company['logo_fit'] ?? 'contain'))?>;border-radius:12px;border:1px solid rgba(148,163,184,0.2);background:#fff;padding:8px;"></div><?php endif; ?><label class="span-all">Address<textarea name="address"><?=htmlspecialchars($company['address'])?></textarea></label></div><div class="form-actions"><button class="button">Save company</button></div></form></div><div class="form-card"><h3>Add another company</h3><p class="panel-sub">Each company has isolated employees, payroll, settings and brand.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=hrCsrf()?>"><input type="hidden" name="new_company" value="1"><div class="form-grid two"><label>Company name<input name="company_name" required></label><label>Unique company code<input name="company_code" placeholder="BRANCH2" required></label><label>Email<input name="email" type="email"></label><label>Phone<input name="phone"></label><label>Brand color<input type="color" name="primary_color" value="#be185d"></label><label>Payroll working days<input type="number" name="payroll_day" value="26" min="1" max="31"></label><label>Logo width<input type="number" min="32" max="300" name="logo_width" value="180"></label><label>Logo height<input type="number" min="24" max="160" name="logo_height" value="52"></label><label>Logo fit<select name="logo_fit"><option value="contain" selected>Contain</option><option value="cover">Cover</option><option value="fill">Fill</option></select></label><label>Company logo<input type="file" name="company_logo" accept=".png,.jpg,.jpeg,.svg,.webp"></label><label class="span-all">Address<textarea name="address"></textarea></label></div><div class="form-actions"><button class="button">Create workspace</button></div></form></div></div>
